def compute(vars):
    current_amount = vars["v1"]
    prior_amount = vars["v2"]

    if prior_amount == 0:
        return None

    change_ratio = ((current_amount - prior_amount) / prior_amount) * 100

    return {
        "value": change_ratio,
        "trace": {
            "current_amount": current_amount,
            "prior_amount": prior_amount,
            "difference": current_amount - prior_amount,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": "$",
                "scale": "million",
                "unit": "percent"
            }
        }
    }
